import { useState } from 'react';
import './dashboard.css';

function Dashboard({ userName, userRole, onLogout }) {
    const [tasks, setTasks] = useState([
        { id: 1, title: "Plan today's tasks", category: 'Personal', priority: 'Medium', startedAt: 'Today', deadline: 'Today', done: true },
        { id: 2, title: 'Complete project work', category: 'Work', priority: 'High', startedAt: 'Today', deadline: 'Tomorrow', done: false },
        { id: 3, title: 'Review your progress', category: 'Personal', priority: 'Low', startedAt: 'Today', deadline: 'Friday', done: false },
    ]);
    const [newTask, setNewTask] = useState('');
    const [newCategory, setNewCategory] = useState('Personal');
    const [newPriority, setNewPriority] = useState('Medium');
    const [newStartedAt, setNewStartedAt] = useState('');
    const [newDeadline, setNewDeadline] = useState('');
    const [filter, setFilter] = useState('All');

    function toggleTask(id) {
        setTasks(tasks.map((task) => (
            task.id === id ? { ...task, done: !task.done } : task
        )));
    }

    function addTask(event) {
        event.preventDefault();
        if (!newTask.trim()) return;
        setTasks([...tasks, { id: Date.now(), title: newTask.trim(), category: newCategory, priority: newPriority, startedAt: newStartedAt || 'Not set', deadline: newDeadline || 'Not set', done: false }]);
        setNewTask('');
        setNewStartedAt('');
        setNewDeadline('');
    }

    function deleteTask(id) {
        setTasks(tasks.filter((task) => task.id !== id));
    }

    const completedTasks = tasks.filter((task) => task.done).length;
    const progressPercent = tasks.length ? Math.round((completedTasks / tasks.length) * 100) : 0;
    const firstLetter = userName.charAt(0).toUpperCase();
    const visibleTasks = tasks.filter((task) => (
        filter === 'All' || (filter === 'Active' && !task.done) || (filter === 'Completed' && task.done)
    ));
    const upcomingTasks = tasks.filter((task) => !task.done).length;
    function formatDateTime(value) {
        if (!value || !value.includes('T')) return value;
        return new Date(value).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' });
    }

    return (
        <main className="dashboard-page">
            <aside className="dashboard-sidebar">
                <h1 className="dashboard-logo">Task Manager</h1>
                <nav aria-label="Main navigation">
                    <button className="nav-item active" type="button">Dashboard</button>
                    <button className="nav-item" type="button">{userRole === 'User' ? 'My Tasks' : 'Team Tasks'}</button>
                    {userRole === 'Admin' && <button className="nav-item" type="button">Manage Users</button>}
                    {userRole === 'Manager' && <button className="nav-item" type="button">Team Members</button>}
                    <button className="nav-item" type="button">Settings</button>
                </nav>
                <button className="sidebar-logout" type="button" onClick={onLogout}>Logout</button>
            </aside>

            <section className="dashboard-main">
                <header className="dashboard-topbar">
                    <div>
                        <p className="dashboard-label">Dashboard</p>
                        <h2>Welcome, {userName}!</h2>
                        <span className="role-badge">{userRole}</span>
                    </div>
                    <div className="user-profile" title={`Signed in as ${userName}`}>
                        <span className="user-avatar">{firstLetter}</span>
                        <span>{userName}</span>
                    </div>
                </header>

                <p className="dashboard-intro">Here is what you have planned for today.</p>

                <section className="stats-grid" aria-label="Task summary">
                    <article className="stat-card"><span>Total Tasks</span><strong>{tasks.length}</strong></article>
                    <article className="stat-card"><span>Completed</span><strong>{completedTasks}</strong></article>
                    <article className="stat-card"><span>Remaining</span><strong>{tasks.length - completedTasks}</strong></article>
                </section>

                <section className="dashboard-grid">
                    <section className="tasks-box" aria-labelledby="tasks-title">
                        <div className="section-heading">
                            <div><p className="section-label">For today</p><h3 id="tasks-title">My Tasks</h3></div>
                            <span>{completedTasks}/{tasks.length}</span>
                        </div>
                        <form className="add-task-form" onSubmit={addTask}>
                            <input value={newTask} onChange={(event) => setNewTask(event.target.value)} placeholder="Add a new task" aria-label="New task" />
                            <select value={newCategory} onChange={(event) => setNewCategory(event.target.value)} aria-label="Task category">
                                <option>Personal</option><option>Work</option><option>Study</option>
                            </select>
                            <select value={newPriority} onChange={(event) => setNewPriority(event.target.value)} aria-label="Task priority">
                                <option>Low</option><option>Medium</option><option>High</option>
                            </select>
                            <label className="date-field">Started at<input type="datetime-local" value={newStartedAt} onChange={(event) => setNewStartedAt(event.target.value)} /></label>
                            <label className="date-field">Deadline<input type="datetime-local" value={newDeadline} onChange={(event) => setNewDeadline(event.target.value)} /></label>
                            <button type="submit">Add</button>
                        </form>
                        <div className="task-filters" aria-label="Task filters">
                            {['All', 'Active', 'Completed'].map((option) => (
                                <button className={filter === option ? 'selected' : ''} key={option} type="button" onClick={() => setFilter(option)}>{option}</button>
                            ))}
                        </div>
                        <div className="task-list">
                            {visibleTasks.length === 0 && <p className="empty-tasks">No {filter.toLowerCase()} tasks.</p>}
                            {visibleTasks.map((task) => (
                                <div className={`task-item ${task.done ? 'completed' : ''}`} key={task.id}>
                                    <input type="checkbox" checked={task.done} onChange={() => toggleTask(task.id)} />
                                    <span className="task-name">{task.title}<small>{task.category} &middot; Started {formatDateTime(task.startedAt)} &middot; Deadline {formatDateTime(task.deadline)}</small></span>
                                    <span className={`priority ${task.priority.toLowerCase()}`}>{task.priority}</span>
                                    <button className="delete-task" type="button" onClick={() => deleteTask(task.id)} aria-label={`Delete ${task.title}`}>x</button>
                                </div>
                            ))}
                        </div>
                    </section>

                    <section className="progress-box" aria-labelledby="progress-title">
                        <p className="section-label">Your progress</p>
                        <h3 id="progress-title">Today&apos;s progress</h3>
                        <div className="progress-circle" style={{ '--progress': `${progressPercent}%` }}><strong>{progressPercent}%</strong></div>
                        <p>{completedTasks === tasks.length ? 'All tasks completed!' : `${upcomingTasks} task${upcomingTasks === 1 ? '' : 's'} left to finish.`}</p>
                    </section>
                </section>
            </section>
        </main>
    );
}

export default Dashboard;
